export const TEXTOS = { es, en, pt };

export function crearTraductor(idioma = "es") {
  const dic = TEXTOS[idioma] || es;
  return (clave, vars = {}) => {
    const plantilla = dic[clave] ?? es[clave] ?? clave;
    return plantilla.replace(/\{(\w+)\}/g, (m, k) => (vars[k] !== undefined && vars[k] !== null ? String(vars[k]) : m));
  };
}
